window.docContents[42].resolve({"/rules/RG1005/#RG1005-proof-shape":{"contents":"The replacement proves the same proposition. Classical, erased proofs are permitted when the surface claims Standard-Logical; executable behavior is a separate account (RG1007, RG3001, RG3002).\n\n","context":"Regula rule reference\u0009Rule index\u0009RG1005: Transitive axioms must fit the selected profile","header":"Required proof shape","id":"/rules/RG1005/#RG1005-proof-shape"},"/rules/RG2004/#RG2004-proof-shape":{"contents":"No proof obligation: the rule concerns the declaration inventory. The removed import must not have supplied evidence the claim still relies on.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG2004: Owned coverage must match the exact Lake inventory","header":"Required proof shape","id":"/rules/RG2004/#RG2004-proof-shape"},"/rules/RG4002/#RG4002-proof-shape":{"contents":"The fence proves exactly the claim the surrounding prose states. A narrower foundation or an execution claim in the prose needs its own evidence; fence success establishes only Standard-Logical admission.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG4002: Positive examples require warning-free elaboration and admission","header":"Required proof shape","id":"/rules/RG4002/#RG4002-proof-shape"},"/rules/RG5001/#RG5001-proof-shape":{"contents":"No proof obligation: the rule checks presence of documentation.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG5001: Claimed modules require module documentation","header":"Required proof shape","id":"/rules/RG5001/#RG5001-proof-shape"}});